    "starterCode": "// Kolleksiyani sinf ichida boshqaring\nimport java.util.Map;\nimport java.util.LinkedHashMap;\n\nclass ShippingAddress {\n    private String street;\n    private String city;\n    public ShippingAddress(String street, String city) {\n        this.street = street;\n        this.city = city;\n    }\n    public String getCity() { return city; }\n}\n\nclass Customer {\n    private String name;\n    private Map<String, ShippingAddress> deliveryAddresses = new LinkedHashMap<>();\n    public Customer(String name) { this.name = name; }\n    public void addDeliveryAddress(String label, ShippingAddress address) {\n        deliveryAddresses.put(label, address);\n    }\n    public Map<String, ShippingAddress> getDeliveryAddresses() {\n        return deliveryAddresses;\n    }\n}\n\nclass Main {\n    public static void main(String[] args) {\n        Customer customer = new Customer(\"Aziz Karimov\");\n        customer.addDeliveryAddress(\"home\", new ShippingAddress(\"12 Amir Temur\", \"Tashkent\"));\n        customer.addDeliveryAddress(\"office\", new ShippingAddress(\"5 Mustaqillik\", \"Tashkent\"));\n        System.out.println(\"Saqlangan manzillar soni: \" + customer.getDeliveryAddresses().size());\n    }\n}",
